CREATE VIEW v117124 AS SELECT x5.v116708 IS FALSE, ST_ASTEXT(ST_ENVELOPE(ST_GEOMFROMTEXT('LINESTRING(0 0)'))) AS x1, NOT AVG(x5.v116707) IS NULL, EXTRACTVALUE(ROLES_GRAPHML(), 'count(//node)') AS x2, INET6_ATON('Жоро') IS NULL, 010101 AS x3, NOT x5.v116708 IS FALSE, ROW_NUMBER() OVER (ORDER BY AVG(x5.v116708)) AS x4 FROM v116706 AS x5